          color: #2c3e50;
          margin-bottom: 10px;
        }

        .dashboard-header p {
          color: #6c757d;
          font-size: 1.1em;
        }

        .active-trip-section {
          margin-bottom: 30px;
        }

        .active-trip-card {
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          padding: 25px;
          border-radius: 15px;
          box-shadow: 0 10px 30px rgba(0,0,0,0.1);
        }

        .trip-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 20px;
        }

        .trip-header h3 {
          margin: 0;
          font-size: 1.5em;
        }

        .trip-dates {
          background: rgba(255,255,255,0.2);
          padding: 5px 15px;
          border-radius: 20px;
          font-size: 0.9em;
        }

        .dashboard-budget-breakdown {
          margin-bottom: 20px;
        }

        .expense-item {
          margin-bottom: 15px;
        }

        .expense-header {
          display: flex;
          justify-content: space-between;
          margin-bottom: 5px;
        }

        .expense-type {
          font-weight: 600;
        }

        .expense-amounts {
          font-size: 0.9em;
        }

        .progress-bar {
          width: 100%;
          height: 8px;
          background-color: rgba(255,255,255,0.3);
          border-radius: 4px;
          overflow: hidden;
          margin-bottom: 5px;
        }

        .progress-fill {
          height: 100%;
          transition: width 0.3s ease;
        }

        .remaining-amount {
          font-size: 0.9em;
          text-align: right;
        }

        .trip-actions {
          display: flex;
          gap: 15px;
          justify-content: center;
        }

        .submit-expense-btn, .complete-trip-btn {
          padding: 12px 25px;
          border: none;
          border-radius: 8px;
          font-weight: 600;
          cursor: pointer;
          transition: all 0.2s ease;
        }

        .submit-expense-btn {
          background: #28a745;
          color: white;
        }

        .complete-trip-btn {
          background: #ffc107;
          color: #212529;
        }

        .no-active-trip {
          text-align: center;
          padding: 40px;
          background: #f8f9fa;
          border-radius: 15px;
          margin-bottom: 30px;
          color: #2c3e50;
        }
        .no-active-trip h2 {
          color: #2c3e50;
        }
        .no-active-trip p {
          color: #6c757d;
        }

        .action-buttons {
          display: flex;
          gap: 15px;
          justify-content: center;
          margin-bottom: 30px;
        }

        .create-trip-btn, .calculate-budget-btn {
          padding: 15px 30px;
          border: none;
          border-radius: 8px;
          font-size: 1.1em;
          font-weight: 600;
          cursor: pointer;
          transition: all 0.2s ease;
        }

        .create-trip-btn {
          background: #007bff;
          color: white;
        }

        .calculate-budget-btn {
          background: #17a2b8;
          color: white;
        }

        .trips-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
          gap: 20px;
        }

        .no-trips {
          text-align: center;
          padding: 40px;
          background: white;
          border-radius: 15px;
          color: #2c3e50;
        }

        .trip-card {
          background: white;
          border-radius: 15px;
          padding: 20px;
          box-shadow: 0 5px 15px rgba(0,0,0,0.1);
          border: 1px solid #e1e8ed;
        }

        .trip-card-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 15px;
        }

        .trip-card-header h3 {
          margin: 0;
          color: #2c3e50;
        }

        .status-badge {
          color: white;
          padding: 4px 12px;
          border-radius: 15px;
          font-size: 0.8em;
          font-weight: 600;
        }

        .trip-details p {
          margin: 8px 0;
          color: #6c757d;
        }

        .activate-btn, .complete-btn {
          padding: 8px 16px;
          border: none;
          border-radius: 6px;
          font-weight: 600;
          cursor: pointer;
          margin-top: 10px;
        }

        .activate-btn {
          background: #28a745;
          color: white;
        }

        .complete-btn {
          background: #ffc107;
          color: #212529;
        }

        .modal-overlay {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: rgba(0,0,0,0.5);
          display: flex;
          justify-content: center;
          align-items: center;
          z-index: 1000;
        }

        .modal {
          background: white;
          border-radius: 15px;
          padding: 30px;
          max-width: 500px;
          width: 90%;
          max-height: 90vh;
          overflow-y: auto;
        }

        .modal-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 20px;
        }

        .close-btn {
          background: none;
          border: none;
          font-size: 24px;
          cursor: pointer;
          color: #6c757d;
        }

        .form-group {
          margin-bottom: 20px;
        }

        .form-group label {
          display: block;
          margin-bottom: 5px;
          font-weight: 600;
          color: #2c3e50;
        }

        .form-group input {
          width: 100%;
          padding: 12px;
          border: 2px solid #e1e8ed;
          border-radius: 8px;
          font-size: 1em;
          color: #2c3e50;
          background: white;
        }

        .form-actions {
          display: flex;
          gap: 15px;
          justify-content: flex-end;
        }

        .cancel-btn, .submit-btn, .calculate-btn {
          padding: 12px 25px;
          border: none;
          border-radius: 8px;
          font-weight: 600;
          cursor: pointer;
        }

        .cancel-btn {
          background: #6c757d;
          color: white;
        }

        .submit-btn, .calculate-btn {
          background: #007bff;
          color: white;
        }

        .calculated-budget {
          margin-top: 20px;
          padding: 20px;
          background: #f8f9fa;
          border-radius: 10px;
          color: #2c3e50;
        }

        .calculated-budget h4 {
          color: #2c3e50;
        }

        .calculated-budget .budget-summary p, 
        .calculated-budget .budget-item span,
        .calculated-budget .total-budget {
          color: #2c3e50;
        }

